class DownloadChoiceRuntimeTest(unittest.TestCase):
 @unittest.skipUnless(shutil.which('java') and shutil.which('javac'),'JDK required')
 def test_native_model_and_recycled_save_dialog(self):
  with tempfile.TemporaryDirectory() as tmp:
   work=pathlib.Path(tmp);sources=dict(STUBS)
   for name in ('DownloadChoice','NativeRead'):sources['cat/narezany/margyt/'+name+'.java']=(ROOT/'inject/java/cat/narezany/margyt'/ (name+'.java')).read_text(encoding='utf-8')
   __import__("android_doubles").with_mod(sources)
   for name,value in sources.items():
    target=work/name;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(value,encoding='utf-8')
   result=subprocess.run(['javac','-source','8','-target','8','-encoding','UTF-8','-d',str(work)]+[str(work/name) for name in sources],capture_output=True,text=True);self.assertEqual(0,result.returncode,result.stderr)
   result=subprocess.run(['java','-cp',str(work),'cat.narezany.margyt.ChoiceHarness'],capture_output=True,text=True);self.assertEqual(0,result.returncode,result.stderr)
